const kbPages = $input.all().map(item => item.json);

function extractText(property) {
  if (!property) return '';
  if (property.rich_text && property.rich_text.length > 0) return property.rich_text[0].plain_text || '';
  if (property.title && property.title.length > 0) return property.title[0].plain_text || '';
  if (property.select) return property.select.name || '';
  if (property.number) return property.number.toString();
  return '';
}

const knowledgeArray = kbPages.map(page => {
  const properties = page.properties || {};
  return {
    name: extractText(properties.Name) || extractText(properties.name) || page.name || '',
    product: extractText(properties.Product) || extractText(properties.product) || '',
    price: extractText(properties.Price) || extractText(properties.price) || '',
    description: extractText(properties.Description) || extractText(properties.description) || ''
  };
}).filter(entry => entry.name || entry.product);

const knowledgeStrings = knowledgeArray.map(entry => 
  `PRODUKT: ${entry.name || 'N/A'}` +
  (entry.product ? ` | TYP: ${entry.product}` : '') +
  (entry.price ? ` | PRIS: ${entry.price}` : '') +
  (entry.description ? ` | BESKRIVNING: ${entry.description}` : '')
);

return [{
  json: {
    ...($input.first()?.json || {}),
    knowledgeContext: knowledgeStrings.join('\n\n') || 'Ingen produktinformation tillgänglig.',
    totalProducts: knowledgeArray.length
  }
}];
